import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-BWBxR0Xs.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/SQLServer/01_%E5%9F%BA%E7%A1%80%E7%AF%87/04_T_SQL%E6%A0%B8%E5%BF%83.html","title":"T-SQL 核心","lang":"zh-CN","frontmatter":{"title":"T-SQL 核心","order":4,"category":["数据库","SQLServer"],"tag":["SQL Server","T-SQL","CTE","动态SQL","JSON"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":8.15,"words":2444},"filePathRelative":"后端开发/数据库/SQLServer/01_基础篇/04_T_SQL核心.md"}`),s={name:`04_T_SQL核心.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="t-sql-核心" tabindex="-1"><a class="header-anchor" href="#t-sql-核心"><span>T-SQL 核心</span></a></h1><blockquote><p><strong>T-SQL 是 SQL Server 的编程语言，不仅仅是查询。</strong> 变量、流程控制、CTE、动态 SQL、JSON——掌握这些，你才能写出真正高效的企业级 SQL。</p></blockquote><hr><h2 id="一、变量与流程控制" tabindex="-1"><a class="header-anchor" href="#一、变量与流程控制"><span>一、变量与流程控制</span></a></h2><h3 id="_1-1-变量声明与赋值" tabindex="-1"><a class="header-anchor" href="#_1-1-变量声明与赋值"><span>1.1 变量声明与赋值</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 声明变量</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @OrderId</span><span style="color:#C678DD;"> INT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1001</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @StartDate</span><span style="color:#C678DD;"> DATETIME2</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> &#39;2024-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @CustomerName</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 赋值</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#E06C75;"> @CustomerName</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> N&#39;张三&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 或通过查询赋值（只返回一行时）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#E06C75;"> @CustomerName</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> CustomerName</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-2-if-else" tabindex="-1"><a class="header-anchor" href="#_1-2-if-else"><span>1.2 IF...ELSE</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Stock</span><span style="color:#C678DD;"> INT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">IF</span><span style="color:#E06C75;"> @Stock</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#C678DD;">    PRINT</span><span style="color:#98C379;"> &#39;库存不足，请及时补货&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 发送告警通知</span></span>
<span class="line"><span style="color:#C678DD;">END</span></span>
<span class="line"><span style="color:#C678DD;">ELSE</span><span style="color:#C678DD;"> IF</span><span style="color:#E06C75;"> @Stock</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#D19A66;"> 50</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#C678DD;">    PRINT</span><span style="color:#98C379;"> &#39;库存偏低&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">END</span></span>
<span class="line"><span style="color:#C678DD;">ELSE</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#C678DD;">    PRINT</span><span style="color:#98C379;"> &#39;库存充足&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">END</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-3-while-循环" tabindex="-1"><a class="header-anchor" href="#_1-3-while-循环"><span>1.3 WHILE 循环</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 批量处理：每次删除 1000 行，避免事务日志膨胀</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @RowsAffected</span><span style="color:#C678DD;"> INT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">WHILE</span><span style="color:#E06C75;"> @RowsAffected</span><span style="color:#56B6C2;"> &gt;</span><span style="color:#D19A66;"> 0</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#C678DD;">    DELETE</span><span style="color:#C678DD;"> TOP</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1000</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> OrderDetails</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#56B6C2;">&lt;</span><span style="color:#98C379;"> &#39;2023-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    SET</span><span style="color:#E06C75;"> @RowsAffected</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> @@ROWCOUNT;</span></span>
<span class="line"><span style="color:#C678DD;">    PRINT</span><span style="color:#98C379;"> &#39;删除了 &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">@RowsAffected</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)) + </span><span style="color:#98C379;">&#39; 行&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">END</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-4-try-catch" tabindex="-1"><a class="header-anchor" href="#_1-4-try-catch"><span>1.4 TRY...CATCH</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#C678DD;"> TRY</span></span>
<span class="line"><span style="color:#C678DD;">    BEGIN</span><span style="color:#C678DD;"> TRANSACTION</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    UPDATE</span><span style="color:#ABB2BF;"> Accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> Balance </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> Balance - </span><span style="color:#D19A66;">500</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> AccountId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    UPDATE</span><span style="color:#ABB2BF;"> Accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> Balance </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> Balance + </span><span style="color:#D19A66;">500</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> AccountId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    COMMIT</span><span style="color:#C678DD;"> TRANSACTION</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">END</span><span style="color:#C678DD;"> TRY</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#C678DD;"> CATCH</span></span>
<span class="line"><span style="color:#C678DD;">    IF</span><span style="color:#ABB2BF;"> @@TRANCOUNT </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 0</span></span>
<span class="line"><span style="color:#C678DD;">        ROLLBACK</span><span style="color:#C678DD;"> TRANSACTION</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    PRINT</span><span style="color:#98C379;"> &#39;错误: &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">ERROR_MESSAGE</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"><span style="color:#C678DD;">    PRINT</span><span style="color:#98C379;"> &#39;严重级别: &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">ERROR_SEVERITY</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"><span style="color:#C678DD;">    PRINT</span><span style="color:#98C379;"> &#39;错误行号: &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">ERROR_LINE</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"><span style="color:#C678DD;">END</span><span style="color:#C678DD;"> CATCH</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-5-case-表达式" tabindex="-1"><a class="header-anchor" href="#_1-5-case-表达式"><span>1.5 CASE 表达式</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 行转列 + 条件分类</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#ABB2BF;">    EmployeeId,</span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Department,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Salary,</span></span>
<span class="line"><span style="color:#C678DD;">    CASE</span></span>
<span class="line"><span style="color:#C678DD;">        WHEN</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 20000</span><span style="color:#C678DD;"> THEN</span><span style="color:#98C379;"> N&#39;高级&#39;</span></span>
<span class="line"><span style="color:#C678DD;">        WHEN</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 12000</span><span style="color:#C678DD;"> THEN</span><span style="color:#98C379;"> N&#39;中级&#39;</span></span>
<span class="line"><span style="color:#C678DD;">        ELSE</span><span style="color:#98C379;"> N&#39;初级&#39;</span></span>
<span class="line"><span style="color:#C678DD;">    END</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> SalaryLevel,</span></span>
<span class="line"><span style="color:#C678DD;">    CASE</span><span style="color:#ABB2BF;"> Department</span></span>
<span class="line"><span style="color:#C678DD;">        WHEN</span><span style="color:#98C379;"> &#39;IT&#39;</span><span style="color:#C678DD;"> THEN</span><span style="color:#98C379;"> &#39;技术&#39;</span></span>
<span class="line"><span style="color:#C678DD;">        WHEN</span><span style="color:#98C379;"> &#39;HR&#39;</span><span style="color:#C678DD;"> THEN</span><span style="color:#98C379;"> &#39;人事&#39;</span></span>
<span class="line"><span style="color:#C678DD;">        WHEN</span><span style="color:#98C379;"> &#39;Sales&#39;</span><span style="color:#C678DD;"> THEN</span><span style="color:#98C379;"> &#39;销售&#39;</span></span>
<span class="line"><span style="color:#C678DD;">        ELSE</span><span style="color:#98C379;"> &#39;其他&#39;</span></span>
<span class="line"><span style="color:#C678DD;">    END</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> DeptName</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、cte-公共表表达式" tabindex="-1"><a class="header-anchor" href="#二、cte-公共表表达式"><span>二、CTE（公共表表达式）</span></a></h2><h3 id="_2-1-普通-cte" tabindex="-1"><a class="header-anchor" href="#_2-1-普通-cte"><span>2.1 普通 CTE</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- CTE：先计算部门平均工资，再筛选高于平均的员工</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> DeptAvg </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Department, </span><span style="color:#56B6C2;">AVG</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> AvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#ABB2BF;"> Department</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">AvgSalary</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">       e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">AvgSalary</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> DiffFromAvg</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees e</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> DeptAvg d </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span><span style="color:#56B6C2;"> &gt;</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">AvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span><span style="color:#C678DD;"> DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-递归-cte" tabindex="-1"><a class="header-anchor" href="#_2-2-递归-cte"><span>2.2 递归 CTE</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 组织架构树：查询某员工的所有下属（含多层）</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> OrgChart </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 锚点：起始节点</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> EmployeeId, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, ManagerId, </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> Level</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> EmployeeId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#7F848E;font-style:italic;">  -- 总经理</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 递归成员：逐层向下</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmployeeId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ManagerId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Level</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees e</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#ABB2BF;"> OrgChart o </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ManagerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmployeeId</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> EmployeeId, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">Level</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#56B6C2;">       REPLICATE</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;  &#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">Level</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) + </span><span style="color:#C678DD;">Name</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> OrgTree</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> OrgChart</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#C678DD;"> Level</span><span style="color:#ABB2BF;">, EmployeeId</span></span>
<span class="line"><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">);  </span><span style="color:#7F848E;font-style:italic;">-- 默认 100，设 0 无限制</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,20),i(d,{code:`eJxLy8kvT85ILCpRCHHhUgACx2ilp3sWPNnRqaDhY6ipFKugq2un4BSt9Gxu39PZs4GCRkBBiEqwlHO00vO+7ie7piBLOYGlXKKVXmzd+rR1LVDKGFXKNVrp5aSNT3Y0I0s5g6XcgA5YO/Np62qYFADSTzNQ`}),o[1]||=n(`<div class="hint-container important"><p class="hint-container-title">递归 CTE 注意事项</p><ol><li>锚点和递归成员的列数、类型必须一致</li><li>递归成员不能包含：GROUP BY、HAVING、TOP、LEFT/RIGHT JOIN（除非递归表在右边）</li><li>默认最大递归 100 层，超过报错，用 <code>OPTION (MAXRECURSION n)</code> 调整</li><li>递归 CTE 可能性能较差，深层级（&gt;1000层）考虑用 HIERARCHYID 或持久化路径</li></ol></div><hr><h2 id="三、临时表-vs-表变量-vs-表值参数" tabindex="-1"><a class="header-anchor" href="#三、临时表-vs-表变量-vs-表值参数"><span>三、临时表 vs 表变量 vs 表值参数</span></a></h2><h3 id="_3-1-临时表-temp-global" tabindex="-1"><a class="header-anchor" href="#_3-1-临时表-temp-global"><span>3.1 临时表（#temp / ##global）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 局部临时表（仅当前会话可见）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> #TempOrders (</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderId </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    CustomerId </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Amount </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> #TempOrders</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrderId, CustomerId, Amount </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#98C379;"> &#39;2024-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 全局临时表（所有会话可见，创建者断开后自动删除）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> ##GlobalSummary (</span></span>
<span class="line"><span style="color:#ABB2BF;">    Department </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    TotalSalary </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-表变量-table" tabindex="-1"><a class="header-anchor" href="#_3-2-表变量-table"><span>3.2 表变量（@table）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @DeptTotals</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    Department </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    TotalAmount </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#E06C75;"> @DeptTotals</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> Department, </span><span style="color:#56B6C2;">SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> TotalAmount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders o </span><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Employees e </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmployeeId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmployeeId</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#E06C75;"> @DeptTotals</span><span style="color:#C678DD;"> ORDER BY</span><span style="color:#ABB2BF;"> TotalAmount </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-3-对比" tabindex="-1"><a class="header-anchor" href="#_3-3-对比"><span>3.3 对比</span></a></h3><table><thead><tr><th>特性</th><th>临时表 (#temp)</th><th>表变量 (@table)</th></tr></thead><tbody><tr><td>作用域</td><td>当前会话</td><td>当前批处理</td></tr><tr><td>统计信息</td><td>✅ 有</td><td>❌ 无（估算固定1行）</td></tr><tr><td>索引</td><td>✅ 可创建</td><td>❌ 仅主键/唯一约束</td></tr><tr><td>事务回滚</td><td>✅ 参与</td><td>❌ 不参与</td></tr><tr><td>日志</td><td>少量</td><td>极少量</td></tr><tr><td>大数据量</td><td>✅ 适合（&gt;1000行）</td><td>❌ 适合小数据（&lt;1000行）</td></tr><tr><td>tempdb 负载</td><td>较重</td><td>较轻</td></tr><tr><td>并发</td><td>会话隔离</td><td>无并发问题</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">选择建议</p><ul><li><strong>&lt; 1000 行</strong>：表变量（无统计信息开销）</li><li><strong>&gt; 1000 行</strong>：临时表（有统计信息，优化器能选更好的计划）</li><li><strong>需要跨存储过程传递表数据</strong>：表值参数（TVP）</li></ul></div><h3 id="_3-4-表值参数-table-valued-parameters" tabindex="-1"><a class="header-anchor" href="#_3-4-表值参数-table-valued-parameters"><span>3.4 表值参数（Table-Valued Parameters）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 定义表类型</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TYPE</span><span style="color:#61AFEF;"> OrderIdTable</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    OrderId </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#C678DD;"> PRIMARY KEY</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 存储过程使用表值参数</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> PROCEDURE</span><span style="color:#D19A66;"> dbo</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">GetOrderDetails</span></span>
<span class="line"><span style="color:#E06C75;">    @OrderIds</span><span style="color:#ABB2BF;"> OrderIdTable </span><span style="color:#C678DD;">READONLY</span></span>
<span class="line"><span style="color:#C678DD;">AS</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Amount</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders o</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#E06C75;"> @OrderIds</span><span style="color:#ABB2BF;"> ids </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> ids</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">END</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 调用</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Ids</span><span style="color:#ABB2BF;"> OrderIdTable;</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#E06C75;"> @Ids</span><span style="color:#C678DD;"> VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1001</span><span style="color:#ABB2BF;">), (</span><span style="color:#D19A66;">1002</span><span style="color:#ABB2BF;">), (</span><span style="color:#D19A66;">1003</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#D19A66;"> dbo</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">GetOrderDetails</span><span style="color:#E06C75;"> @Ids</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、动态-sql" tabindex="-1"><a class="header-anchor" href="#四、动态-sql"><span>四、动态 SQL</span></a></h2><h3 id="_4-1-sp-executesql-参数化-安全" tabindex="-1"><a class="header-anchor" href="#_4-1-sp-executesql-参数化-安全"><span>4.1 sp_executesql（参数化，安全）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- ✅ 参数化动态 SQL：防注入 + 计划缓存复用</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Sql</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(MAX) </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> N</span><span style="color:#98C379;">&#39;</span></span>
<span class="line"><span style="color:#98C379;">    SELECT OrderId, CustomerId, Amount</span></span>
<span class="line"><span style="color:#98C379;">    FROM Orders</span></span>
<span class="line"><span style="color:#98C379;">    WHERE CustomerId = @CustId AND OrderDate &gt;= @StartDate&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;"> sp_executesql</span></span>
<span class="line"><span style="color:#E06C75;">    @Sql</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#98C379;">    N&#39;@CustId INT, @StartDate DATETIME2(3)&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    @CustId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1001</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    @StartDate</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;2024-01-01&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-exec-非参数化-有注入风险" tabindex="-1"><a class="header-anchor" href="#_4-2-exec-非参数化-有注入风险"><span>4.2 EXEC（非参数化，有注入风险）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- ❌ 字符串拼接：有 SQL 注入风险！</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Dept</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> N&#39;IT&#39;&#39;;</span></span>
<span class="line"><span style="color:#98C379;">DELETE FROM Employees; --&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;SELECT * FROM Employees WHERE Department = &#39;&#39;&#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#E06C75;">@Dept</span><span style="color:#ABB2BF;"> + </span><span style="color:#98C379;">&#39;&#39;&#39;&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 实际执行: SELECT * FROM Employees WHERE Department = &#39;IT&#39;; DELETE FROM Employees; --&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">永远用 sp_executesql 替代 EXEC</p><ul><li><strong>sp_executesql</strong>：参数化，防注入，计划可缓存复用</li><li><strong>EXEC</strong>：字符串拼接，SQL 注入风险，每次生成新计划</li><li>只有在无法参数化的场景（如动态表名、动态列名）才用 EXEC，且必须用 <code>QUOTENAME()</code> 防注入</li></ul></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 动态表名/列名：用 QUOTENAME 防注入</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @TableName</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> N&#39;Orders&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @ColumnName</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">128</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#98C379;"> N&#39;Amount&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Sql</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(MAX);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#E06C75;"> @Sql</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> N&#39;SELECT &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">QUOTENAME</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">@ColumnName</span><span style="color:#ABB2BF;">) + </span><span style="color:#98C379;">N&#39; FROM &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">QUOTENAME</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">@TableName</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">EXEC</span><span style="color:#ABB2BF;"> sp_executesql </span><span style="color:#E06C75;">@Sql</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- QUOTENAME(&#39;Orders&#39;) → [Orders]</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- QUOTENAME(&#39;Orders; DROP TABLE Users--&#39;) → [Orders; DROP TABLE Users--]（被安全引用）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="五、merge-语句" tabindex="-1"><a class="header-anchor" href="#五、merge-语句"><span>五、MERGE 语句</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MERGE：根据条件 INSERT / UPDATE / DELETE（常用于 ETL 同步）</span></span>
<span class="line"><span style="color:#C678DD;">MERGE</span><span style="color:#C678DD;"> INTO</span><span style="color:#ABB2BF;"> Employees </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> target</span></span>
<span class="line"><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> EmployeeId, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, Department, Salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> EmployeeStaging) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> source</span></span>
<span class="line"><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> target</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmployeeId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmployeeId</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">WHEN</span><span style="color:#C678DD;"> MATCHED</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#D19A66;">    target</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#56B6C2;"> &lt;&gt;</span><span style="color:#D19A66;"> source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span></span>
<span class="line"><span style="color:#C678DD;">    OR</span><span style="color:#D19A66;"> target</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#56B6C2;"> &lt;&gt;</span><span style="color:#D19A66;"> source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span></span>
<span class="line"><span style="color:#C678DD;">    OR</span><span style="color:#D19A66;"> target</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span><span style="color:#56B6C2;"> &lt;&gt;</span><span style="color:#D19A66;"> source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span></span>
<span class="line"><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">THEN</span></span>
<span class="line"><span style="color:#C678DD;">    UPDATE</span><span style="color:#C678DD;"> SET</span></span>
<span class="line"><span style="color:#D19A66;">        target</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">        target</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">        target</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">WHEN</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> MATCHED</span><span style="color:#C678DD;"> THEN</span></span>
<span class="line"><span style="color:#C678DD;">    INSERT</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, Department, Salary)</span></span>
<span class="line"><span style="color:#C678DD;">    VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Department</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">source</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Salary</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">WHEN</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> MATCHED</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> SOURCE </span><span style="color:#C678DD;">THEN</span></span>
<span class="line"><span style="color:#C678DD;">    DELETE</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">MERGE 的坑</p><ol><li>在某些 SQL Server 版本中，MERGE 可能对同一行执行多次操作（违反标准语义）</li><li>MERGE 持有更长时间的锁，高并发下可能造成阻塞</li><li>建议：对简单 UPSERT 用 <code>IF EXISTS ... UPDATE ELSE INSERT</code> 替代</li><li>如必须用 MERGE，加上 <code>HOLDLOCK</code> 提示保护并发</li></ol></div><hr><h2 id="六、分页-offset-fetch" tabindex="-1"><a class="header-anchor" href="#六、分页-offset-fetch"><span>六、分页：OFFSET...FETCH</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- SQL Server 2012+ 标准分页</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrderId, CustomerId, OrderDate, Amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">, OrderId </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#ABB2BF;">OFFSET </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> ROWS</span><span style="color:#C678DD;"> FETCH</span><span style="color:#C678DD;"> NEXT</span><span style="color:#D19A66;"> 20</span><span style="color:#C678DD;"> ROWS</span><span style="color:#ABB2BF;"> ONLY;  </span><span style="color:#7F848E;font-style:italic;">-- 第1页</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 参数化分页</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @PageNumber</span><span style="color:#C678DD;"> INT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @PageSize</span><span style="color:#C678DD;"> INT</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 20</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrderId, CustomerId, OrderDate, Amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">, OrderId </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#ABB2BF;">OFFSET (</span><span style="color:#E06C75;">@PageNumber</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) * </span><span style="color:#E06C75;">@PageSize</span><span style="color:#C678DD;"> ROWS</span></span>
<span class="line"><span style="color:#C678DD;">FETCH</span><span style="color:#C678DD;"> NEXT</span><span style="color:#E06C75;"> @PageSize</span><span style="color:#C678DD;"> ROWS</span><span style="color:#ABB2BF;"> ONLY;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">OFFSET...FETCH 性能</p><ul><li><strong>前几页</strong>：性能好（只扫描少量行）</li><li><strong>深分页</strong>（如第 10000 页）：需要先跳过前面所有行，性能差</li><li>深分页优化：用 Keyset Pagination（WHERE Key &gt; lastSeenKey）</li></ul></div><hr><h2 id="七、字符串与-json-函数" tabindex="-1"><a class="header-anchor" href="#七、字符串与-json-函数"><span>七、字符串与 JSON 函数</span></a></h2><h3 id="_7-1-字符串函数-2016" tabindex="-1"><a class="header-anchor" href="#_7-1-字符串函数-2016"><span>7.1 字符串函数（2016+）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- STRING_AGG：字符串聚合（2017+）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> Department,</span></span>
<span class="line"><span style="color:#56B6C2;">       STRING_AGG</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;, &#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">WITHIN</span><span style="color:#56B6C2;"> GROUP</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> EmployeeList</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">GROUP BY</span><span style="color:#ABB2BF;"> Department;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- IT: 张三, 王五, 赵六</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- STRING_SPLIT：字符串拆分（2016+）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> value</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> Tag</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#56B6C2;"> STRING_SPLIT</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;C#,SQL,Python,Docker&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;,&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- C# / SQL / Python / Docker</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- CONCAT_WS：带分隔符拼接，自动忽略 NULL（2017+）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> CONCAT_WS(</span><span style="color:#98C379;">&#39; - &#39;</span><span style="color:#ABB2BF;">, FirstName, MiddleName, LastName) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> FullName</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Users;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-json-函数" tabindex="-1"><a class="header-anchor" href="#_7-2-json-函数"><span>7.2 JSON 函数</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- FOR JSON PATH：查询结果转 JSON</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> OrderId, CustomerId, Amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1001</span></span>
<span class="line"><span style="color:#C678DD;">FOR</span><span style="color:#C678DD;"> JSON</span><span style="color:#C678DD;"> PATH</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- [{&quot;OrderId&quot;:1001,&quot;CustomerId&quot;:1001,&quot;Amount&quot;:500.00}, ...]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- OPENJSON：解析 JSON 为行集</span></span>
<span class="line"><span style="color:#C678DD;">DECLARE</span><span style="color:#E06C75;"> @Json</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(MAX) </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> N</span><span style="color:#98C379;">&#39;[</span></span>
<span class="line"><span style="color:#98C379;">    {&quot;ProductId&quot;:1, &quot;Name&quot;:&quot;iPhone 15&quot;, &quot;Price&quot;:6999},</span></span>
<span class="line"><span style="color:#98C379;">    {&quot;ProductId&quot;:2, &quot;Name&quot;:&quot;MacBook Pro&quot;, &quot;Price&quot;:14999}</span></span>
<span class="line"><span style="color:#98C379;">]&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> ProductId, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, Price</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#56B6C2;"> OPENJSON</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">@Json</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    ProductId </span><span style="color:#C678DD;">INT</span><span style="color:#98C379;"> &#39;$.ProductId&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">200</span><span style="color:#ABB2BF;">) </span><span style="color:#98C379;">&#39;$.Name&#39;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Price </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">18</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#98C379;">&#39;$.Price&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- JSON_VALUE：提取标量值</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> JSON_VALUE</span><span style="color:#ABB2BF;">(Attributes, </span><span style="color:#98C379;">&#39;$.Color&#39;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> Color</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Products;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- JSON_MODIFY：修改 JSON 值</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> Products</span></span>
<span class="line"><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> Attributes </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> JSON_MODIFY</span><span style="color:#ABB2BF;">(Attributes, </span><span style="color:#98C379;">&#39;$.Color&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;白色&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> ProductId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="八、cross-apply-outer-apply" tabindex="-1"><a class="header-anchor" href="#八、cross-apply-outer-apply"><span>八、CROSS APPLY / OUTER APPLY</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- CROSS APPLY：类似 INNER JOIN，但右边可以是表值函数或子查询</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 场景：获取每个客户最近 3 笔订单</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerName</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers c</span></span>
<span class="line"><span style="color:#C678DD;">CROSS</span><span style="color:#C678DD;"> APPLY</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;"> OrderId, Amount</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span></span>
<span class="line"><span style="color:#C678DD;">    ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#ABB2BF;">) o;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- OUTER APPLY：类似 LEFT JOIN，左边没匹配也返回</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerName</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">OrderId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers c</span></span>
<span class="line"><span style="color:#C678DD;">OUTER</span><span style="color:#C678DD;"> APPLY</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#C678DD;"> TOP</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;"> OrderId, Amount</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Orders</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span></span>
<span class="line"><span style="color:#C678DD;">    ORDER BY</span><span style="color:#ABB2BF;"> OrderDate </span><span style="color:#C678DD;">DESC</span></span>
<span class="line"><span style="color:#ABB2BF;">) o;  </span><span style="color:#7F848E;font-style:italic;">-- 没有订单的客户也会返回，OrderId/Amount 为 NULL</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">APPLY vs JOIN</p><ul><li><strong>JOIN</strong>：右边不能引用左边的列（关联条件在 ON 中）</li><li><strong>APPLY</strong>：右边可以引用左边的列，类似 LATERAL JOIN</li><li><strong>CROSS APPLY</strong> = INNER JOIN 语义（必须匹配）</li><li><strong>OUTER APPLY</strong> = LEFT JOIN 语义（允许不匹配）</li></ul></div><hr><h2 id="九、exists-vs-in-vs-join" tabindex="-1"><a class="header-anchor" href="#九、exists-vs-in-vs-join"><span>九、EXISTS vs IN vs JOIN</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查询有订单的客户</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. EXISTS：外表驱动，找到一条就返回（推荐大子查询）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers c</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> Orders o </span><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. IN：先算子查询结果集，再匹配（推荐小子查询）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Orders);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. JOIN：可能产生重复行（需要 DISTINCT）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT DISTINCT</span><span style="color:#ABB2BF;"> c.* </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers c</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Orders o </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>场景</th><th>推荐</th><th>原因</th></tr></thead><tbody><tr><td>子查询结果集小</td><td>IN</td><td>一次性获取，哈希匹配效率高</td></tr><tr><td>外表小、子查询大</td><td>EXISTS</td><td>找到即停，避免全量扫描</td></tr><tr><td>需要返回两表数据</td><td>JOIN</td><td>直接获取两表列</td></tr><tr><td>NOT 语义</td><td>NOT EXISTS</td><td>NOT IN 遇 NULL 结果为空</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">NOT IN 的 NULL 陷阱</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 如果子查询包含 NULL，NOT IN 返回空结果！</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> CustomerId </span><span style="color:#C678DD;">NOT</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> ManagerId </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Employees);</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 如果 ManagerId 有 NULL，结果为空！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 安全写法：用 NOT EXISTS</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Customers c</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> EXISTS</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> Employees e </span><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> e</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ManagerId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">CustomerId</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><hr><h2 id="十、面试技巧" tabindex="-1"><a class="header-anchor" href="#十、面试技巧"><span>十、面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频考点</p><ol><li><strong>CTE vs 临时表</strong>：CTE 是语法糖（非物化），临时表有统计信息可索引；大数据用临时表</li><li><strong>表变量 vs 临时表</strong>：表变量无统计信息（估算1行），&gt;1000行用临时表</li><li><strong>sp_executesql vs EXEC</strong>：参数化 vs 拼接，安全 vs 注入，计划复用 vs 每次编译</li><li><strong>OFFSET...FETCH 深分页</strong>：性能问题及 Keyset Pagination 优化方案</li><li><strong>NOT IN vs NOT EXISTS</strong>：NULL 值导致 NOT IN 返回空集</li><li><strong>CROSS APPLY 使用场景</strong>：每行关联的 TOP-N 子查询</li><li><strong>JSON 函数</strong>：FOR JSON / OPENJSON / JSON_VALUE / JSON_MODIFY</li></ol></div><div class="hint-container warning"><p class="hint-container-title">易错点</p><ul><li>&quot;CTE 会物化数据&quot;——❌，CTE 只是内联展开，每次引用都重新计算</li><li>&quot;表变量在内存中&quot;——❌，大数据时也会写入 tempdb</li><li>&quot;MERGE 是原子操作&quot;——不一定，某些情况下可能对同一行多次操作</li><li>&quot;OFFSET...FETCH 深分页性能好&quot;——❌，越深的页越慢</li></ul></div><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://learn.microsoft.com/en-us/sql/t-sql/language-reference" target="_blank" rel="noopener noreferrer">T-SQL Reference</a></li><li><a href="https://learn.microsoft.com/en-us/sql/t-sql/queries/with-common-table-expression-transact-sql" target="_blank" rel="noopener noreferrer">WITH common_table_expression</a></li><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/system-stored-procedures/sp-executesql-transact-sql" target="_blank" rel="noopener noreferrer">sp_executesql</a></li><li><a href="https://learn.microsoft.com/en-us/sql/relational-databases/json/json-data-sql-server" target="_blank" rel="noopener noreferrer">JSON Data in SQL Server</a></li><li><a href="https://github.com/abpframework/abp" target="_blank" rel="noopener noreferrer">ABP Framework GitHub</a></li></ul>`,50)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};